-- Comentarios do CTN, lote 9 (arts. 187 a 208-J). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 187 and 208 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(187,'','Cobrança judicial do crédito tributário e concurso de credores','A cobrança judicial do crédito tributário não é sujeita a concurso de credores ou habilitação em falência, recuperação judicial, concordata, inventário ou arrolamento (redação dada pela Lei Complementar n. 118, de 2005; o texto traz a anotação "Vide ADPF 357"). O parágrafo único dispõe que o concurso de preferência somente se verifica entre pessoas jurídicas de direito público, na seguinte ordem: União (inciso I); Estados, Distrito Federal e Territórios, conjuntamente e pro rata (inciso II); e Municípios, conjuntamente e pro rata (inciso III). Os incisos também trazem a anotação "Vide ADPF 357".'),
(188,'','Créditos extraconcursais na falência','São extraconcursais os créditos tributários decorrentes de fatos geradores ocorridos no curso do processo de falência (redação dada pela Lei Complementar n. 118, de 2005). O § 1º dispõe que, contestado o crédito tributário, o juiz remeterá as partes ao processo competente, mandando reservar bens suficientes à extinção total do crédito e seus acrescidos, se a massa não puder efetuar a garantia da instância por outra forma, ouvido, quanto à natureza e valor dos bens reservados, o representante da Fazenda Pública interessada. O § 2º dispõe que o artigo aplica-se aos processos de concordata.'),
(189,'','Créditos tributários em inventário ou arrolamento','São pagos preferencialmente a quaisquer créditos habilitados em inventário ou arrolamento, ou a outros encargos do monte, os créditos tributários vencidos ou vincendos, a cargo do de cujus ou de seu espólio, exigíveis no decurso do processo de inventário ou arrolamento. O parágrafo único dispõe que, contestado o crédito tributário, proceder-se-á na forma do disposto no § 1º do artigo anterior.'),
(190,'','Créditos tributários na liquidação de pessoas jurídicas','São pagos preferencialmente a quaisquer outros os créditos tributários vencidos ou vincendos, a cargo de pessoas jurídicas de direito privado em liquidação judicial ou voluntária, exigíveis no decurso da liquidação.'),
(191,'','Extinção das obrigações do falido','A extinção das obrigações do falido requer prova de quitação de todos os tributos (redação dada pela Lei Complementar n. 118, de 2005).'),
(191,'Art. 191-A','Recuperação judicial e prova de quitação de tributos','A concessão de recuperação judicial depende da apresentação da prova de quitação de todos os tributos, observado o disposto nos arts. 151, 205 e 206 do CTN (artigo incluído pela Lei Complementar n. 118, de 2005).'),
(192,'','Prova de quitação na partilha ou adjudicação','Nenhuma sentença de julgamento de partilha ou adjudicação será proferida sem prova da quitação de todos os tributos relativos aos bens do espólio, ou às suas rendas.'),
(193,'','Prova de quitação em contratos e concorrências públicas','Salvo quando expressamente autorizado por lei, nenhum departamento da administração pública da União, dos Estados, do Distrito Federal ou dos Municípios, ou sua autarquia, celebrará contrato ou aceitará proposta em concorrência pública sem que o contratante ou proponente faça prova da quitação de todos os tributos devidos à Fazenda Pública interessada, relativos à atividade em cujo exercício contrata ou concorre.'),
(194,'','Fiscalização: competência, programas de conformidade e prevenção de conflitos','A legislação tributária, observado o disposto no CTN, regulará, em caráter geral, ou especificamente em função da natureza do tributo de que se tratar, a competência e os poderes das autoridades administrativas em matéria de fiscalização da sua aplicação. O § 1º dispõe que a legislação a que se refere o artigo aplica-se às pessoas naturais ou jurídicas, contribuintes ou não, inclusive às que gozem de imunidade tributária ou de isenção de caráter pessoal. O § 2º, incluído pela Lei Complementar n. 236, de 2026, dispõe que a administração tributária deverá priorizar e disponibilizar métodos preventivos para possibilitar ao sujeito passivo autorregularizar o pagamento dos tributos e das obrigações acessórias antes da lavratura do auto de infração, nos termos da legislação específica. O § 3º dispõe que a administração tributária estabelecerá programas de conformidade e outras medidas com vistas à prevenção de conflitos, que deverão assegurar o diálogo e a plena compreensão objetiva e subjetiva de divergências ou de disputas acerca da interpretação ou da aplicação da legislação tributária e aduaneira, com base nos princípios da voluntariedade de ingresso e de saída (inciso I); boa-fé e construção de uma relação de confiança mútua (inciso II); diálogo e cooperação (inciso III); transparência, previsibilidade e segurança jurídica (inciso IV); busca da conformidade tributária (inciso V); prevenção de litígios e de imposição de penalidades (inciso VI); e proporcionalidade e imparcialidade (inciso VII).'),
(194,'Art. 194-A','Efeito vinculante das decisões do STF e do STJ sobre a administração tributária','O trânsito em julgado da decisão definitiva do Supremo Tribunal Federal e do Superior Tribunal de Justiça com efeito vinculante no âmbito judicial vinculará também a administração tributária (Lei Complementar n. 236, de 2026). O § 1º dispõe que, no prazo máximo de 90 (noventa) dias úteis, contado do trânsito em julgado da decisão, a Fazenda Pública, por parecer jurídico devidamente fundamentado, dará publicidade ao fato, inclusive quanto à aplicação da orientação adotada em relação aos seus créditos tributários e aduaneiros (inciso I), aos temas em que deixará de impugnar pleitos do sujeito passivo nas esferas administrativa e judicial (inciso II) e aos temas em que desistirá de impugnações ou recursos já formulados (inciso III). O § 2º dispõe que, a fim de observar precedentes formados em tribunais superiores em sentido favorável ao sujeito passivo, os órgãos de representação judicial das Fazendas Públicas poderão estabelecer outras hipóteses de impedimento à inscrição do crédito na respectiva dívida ativa. O § 3º trata dos instrumentos de gestão que os órgãos de administração tributária e de representação judicial desenvolverão para orientação periódica de seus membros e servidores acerca de precedentes e da legislação tributária e aduaneira, nos termos do parágrafo.'),
(195,'','Exame de mercadorias, livros e documentos','Para os efeitos da legislação tributária, não têm aplicação quaisquer disposições legais excludentes ou limitativas do direito de examinar mercadorias, livros, arquivos, documentos, papéis e efeitos comerciais ou fiscais, dos comerciantes industriais ou produtores, ou da obrigação destes de exibi-los. O parágrafo único dispõe que os livros obrigatórios de escrituração comercial e fiscal e os comprovantes dos lançamentos neles efetuados serão conservados até que ocorra a prescrição dos créditos tributários decorrentes das operações a que se refiram.'),
(196,'','Termos de fiscalização e documento de início do procedimento','A autoridade administrativa que proceder ou presidir quaisquer diligências de fiscalização lavrará os termos necessários para que se documente o procedimento, na forma da legislação aplicável. O § 1º dispõe que os termos serão lavrados, sempre que possível, em um dos livros fiscais exibidos e que, quando lavrados em separado, entregar-se-á à pessoa sujeita à fiscalização cópia autenticada pela autoridade. O § 2º, incluído pela Lei Complementar n. 236, de 2026, dispõe que o procedimento de fiscalização será precedido de emissão de documento que preveja o seu início, contendo a identificação da autoridade responsável pela emissão, das autoridades encarregadas pela fiscalização, do contribuinte e de seus estabelecimentos objeto da fiscalização (inciso I); os trabalhos a serem desenvolvidos, com a identificação do objeto da fiscalização, o período a ser examinado e o rol de documentos fiscais necessários (inciso II); a forma de confirmação de sua autenticidade pelo contribuinte (inciso III); e o prazo de duração do procedimento (inciso IV). O § 3º dispõe que a fiscalização em estabelecimento ou domicílio do contribuinte deverá ser feita mediante a entrega de uma das vias desse documento ao contribuinte, seu representante legal ou preposto. O § 4º dispõe que o acompanhamento de força policial será condicionado ao justo receio de resistência ao ato fiscalizatório, que deverá ser reduzido a termo e constará do documento entregue ao contribuinte.'),
(197,'','Dever de informar à autoridade administrativa','Mediante intimação escrita, são obrigados a prestar à autoridade administrativa todas as informações de que disponham com relação aos bens, negócios ou atividades de terceiros os tabeliães, escrivães e demais serventuários de ofício (inciso I); os bancos, casas bancárias, Caixas Econômicas e demais instituições financeiras (inciso II); as empresas de administração de bens (inciso III); os corretores, leiloeiros e despachantes oficiais (inciso IV); os inventariantes (inciso V); os síndicos, comissários e liquidatários (inciso VI); e quaisquer outras entidades ou pessoas que a lei designe, em razão de seu cargo, ofício, função, ministério, atividade ou profissão (inciso VII). O parágrafo único dispõe que a obrigação não abrange a prestação de informações quanto a fatos sobre os quais o informante esteja legalmente obrigado a observar segredo em razão de cargo, ofício, função, ministério, atividade ou profissão.'),
(198,'','Sigilo fiscal','Sem prejuízo do disposto na legislação criminal, é vedada a divulgação, por parte da Fazenda Pública ou de seus servidores, de informação obtida em razão do ofício sobre a situação econômica ou financeira do sujeito passivo ou de terceiros e sobre a natureza e o estado de seus negócios ou atividades (redação dada pela Lei Complementar n. 104, de 2001). O § 1º excetua, além dos casos do art. 199, a requisição de autoridade judiciária no interesse da justiça (inciso I) e as solicitações de autoridade administrativa no interesse da Administração Pública, desde que comprovada a instauração regular de processo administrativo, no órgão ou na entidade respectiva, com o objetivo de investigar o sujeito passivo a que se refere a informação, por prática de infração administrativa (inciso II). O § 2º dispõe que o intercâmbio de informação sigilosa, no âmbito da Administração Pública, será realizado mediante processo regularmente instaurado, e a entrega será feita pessoalmente à autoridade solicitante, mediante recibo, que formalize a transferência e assegure a preservação do sigilo. O § 3º dispõe que não é vedada a divulgação de informações relativas a representações fiscais para fins penais (inciso I); inscrições na Dívida Ativa da Fazenda Pública (inciso II); parcelamento ou moratória (inciso III); e incentivo, renúncia, benefício ou imunidade de natureza tributária cujo beneficiário seja pessoa jurídica (inciso IV). O § 4º, incluído pela Lei Complementar n. 208, de 2024, dispõe que, sem prejuízo do art. 197, a administração tributária poderá requisitar informações cadastrais e patrimoniais de sujeito passivo de crédito tributário a órgãos ou entidades, públicos ou privados, que operem cadastros e registros ou controlem operações de bens e direitos. O § 5º dispõe que, independentemente dessa requisição, os órgãos e entidades da administração pública direta e indireta de qualquer dos Poderes colaborarão com a administração tributária visando ao compartilhamento de bases de dados de natureza cadastral e patrimonial de seus administrados e supervisionados.'),
(199,'','Assistência mútua entre Fazendas Públicas','A Fazenda Pública da União e as dos Estados, do Distrito Federal e dos Municípios prestar-se-ão mutuamente assistência para a fiscalização dos tributos respectivos e permuta de informações, na forma estabelecida, em caráter geral ou específico, por lei ou convênio. O parágrafo único dispõe que a Fazenda Pública da União, na forma estabelecida em tratados, acordos ou convênios, poderá permutar informações com Estados estrangeiros no interesse da arrecadação e da fiscalização de tributos.'),
(199,'Art. 199-A','Compartilhamento de atividades entre Fazendas Públicas','As Fazendas Públicas da União, dos Estados, do Distrito Federal e dos Municípios poderão estabelecer entre si, mediante convênio, o compartilhamento das atividades de fiscalização, lançamento e cobrança de tributos e de sua estrutura destinada ao processo administrativo fiscal, com vistas à otimização do exercício de sua capacidade tributária (Lei Complementar n. 236, de 2026).'),
(200,'','Requisição de força pública','As autoridades administrativas federais poderão requisitar o auxílio da força pública federal, estadual ou municipal, e reciprocamente, quando vítimas de embaraço ou desacato no exercício de suas funções, ou quando necessário à efetivação de medida prevista na legislação tributária, ainda que não se configure fato definido em lei como crime ou contravenção.'),
(201,'','Dívida ativa tributária','Constitui dívida ativa tributária a proveniente de crédito dessa natureza, regularmente inscrita na repartição administrativa competente, depois de esgotado o prazo fixado, para pagamento, pela lei ou por decisão final proferida em processo regular. O § 1º dispõe que a fluência de juros de mora não exclui, para os efeitos do artigo, a liquidez do crédito. O § 2º, incluído pela Lei Complementar n. 236, de 2026, dispõe que o controle de legalidade da inscrição em dívida ativa consiste na análise, pela Fazenda Pública, dos requisitos de certeza, liquidez e exigibilidade, essenciais à formação do título executivo, e constitui direito do contribuinte e dever da Fazenda Pública credora, que poderá realizá-lo a qualquer tempo, de ofício ou a requerimento do interessado. O § 3º dispõe que o órgão responsável pela constituição do crédito deve encaminhar todas as informações necessárias para a inscrição em dívida ativa e a cobrança, administrativa ou judicial, dos créditos de natureza tributária ou não tributária, definitivamente constituídos ou reconhecidos pelo sujeito passivo, no prazo máximo de 90 dias úteis a partir de sua exigibilidade, podendo ser ampliado a até 120 dias úteis para contribuintes de maior índice de conformidade e reduzido para 60 dias úteis para aqueles com histórico de baixo recolhimento espontâneo, salvo disposição de lei em sentido contrário.'),
(202,'','Termo de inscrição da dívida ativa','O termo de inscrição da dívida ativa, autenticado pela autoridade competente, indicará obrigatoriamente o nome do devedor e dos corresponsáveis, bem como, sempre que possível, o domicílio ou a residência daquele e destes (inciso I); a quantia devida e a maneira de calcular os juros de mora acrescidos (inciso II); a origem e natureza do crédito, mencionada especificamente a disposição da lei em que seja fundado (inciso III); a data em que foi inscrita (inciso IV); e, sendo caso, o número do processo administrativo de que se originar o crédito (inciso V). O § 1º dispõe que a certidão conterá, além dos requisitos do artigo, a indicação do livro e da folha da inscrição. O § 2º consta como vetado e está registrado como não vigente.'),
(203,'','Nulidade da inscrição da dívida ativa','A omissão de quaisquer dos requisitos previstos no artigo anterior, ou o erro a eles relativo, são causas de nulidade da inscrição e do processo de cobrança dela decorrente, mas a nulidade poderá ser sanada até a decisão de primeira instância, mediante substituição da certidão nula, devolvido ao sujeito passivo, acusado ou interessado o prazo para defesa, que somente poderá versar sobre a parte modificada.'),
(204,'','Presunção de certeza e liquidez da dívida ativa','A dívida regularmente inscrita goza da presunção de certeza e liquidez e tem o efeito de prova pré-constituída. O parágrafo único dispõe que a presunção é relativa e pode ser ilidida por prova inequívoca, a cargo do sujeito passivo ou do terceiro a que aproveite.'),
(205,'','Certidão negativa','A lei poderá exigir que a prova da quitação de determinado tributo, quando exigível, seja feita por certidão negativa, expedida à vista de requerimento do interessado, que contenha todas as informações necessárias à identificação de sua pessoa, domicílio fiscal e ramo de negócio ou atividade e indique o período a que se refere o pedido. O parágrafo único dispõe que a certidão negativa será sempre expedida nos termos em que tenha sido requerida e será fornecida dentro de 10 (dez) dias da data da entrada do requerimento na repartição. Os §§ 1º e 2º constam como vetados e estão registrados como não vigentes.'),
(206,'','Certidão positiva com efeitos de negativa','Tem os mesmos efeitos previstos no artigo anterior a certidão de que conste a existência de créditos não vencidos, em curso de cobrança executiva em que tenha sido efetivada a penhora, ou cuja exigibilidade esteja suspensa.'),
(207,'','Dispensa da prova de quitação','Independentemente de disposição legal permissiva, será dispensada a prova de quitação de tributos, ou o seu suprimento, quando se tratar de prática de ato indispensável para evitar a caducidade de direito, respondendo, porém, todos os participantes no ato pelo tributo porventura devido, juros de mora e penalidades cabíveis, exceto as relativas a infrações cuja responsabilidade seja pessoal ao infrator.'),
(208,'','Responsabilidade do funcionário que expede certidão negativa com dolo ou fraude','A certidão negativa expedida com dolo ou fraude, que contenha erro contra a Fazenda Pública, responsabiliza pessoalmente o funcionário que a expedir, pelo crédito tributário e juros de mora acrescidos. O parágrafo único dispõe que o disposto no artigo não exclui a responsabilidade criminal e funcional que no caso couber.'),
(208,'Art. 208-A','Processo administrativo fiscal: normas gerais','O Capítulo estabelece normas gerais para regular o processo administrativo fiscal no âmbito das administrações tributárias da União, dos Estados, do Distrito Federal e dos Municípios, com vistas, em especial, a assegurar aos litigantes o devido processo legal, o contraditório, a ampla defesa e o duplo grau de jurisdição (Lei Complementar n. 236, de 2026). O § 1º dispõe que, no contencioso administrativo fiscal, os entes federativos com mais de 100.000 habitantes residentes deverão assegurar aos contribuintes o duplo grau de jurisdição, nos termos da legislação específica. O § 2º dispõe que, para definir a população residente, será utilizado o último censo demográfico divulgado pelo IBGE.'),
(208,'Art. 208-B','Auto de infração: conteúdo obrigatório','O auto de infração será lavrado com base nos elementos de prova disponíveis e conterá obrigatoriamente a identificação do autuado (inciso I); a descrição clara dos fatos (inciso II); o dispositivo legal infringido e a penalidade aplicada (inciso III); a subsunção dos fatos descritos ao dispositivo legal infringido (inciso IV); a determinação da exigência fiscal e a intimação para cumpri-la ou impugná-la no prazo legal (inciso V); o local, a data e a hora da lavratura (inciso VI); e a assinatura do autuante, a indicação de seu cargo ou função e o número de matrícula (inciso VII).'),
(208,'Art. 208-C','Julgamento dos processos de exigência de tributos e penalidades','O julgamento dos processos de exigência de tributos e penalidades previstos na legislação tributária e de outros que lhes são correlatos observará que a apresentação tempestiva de impugnação terá o efeito de instaurar o contencioso administrativo fiscal, suspendendo a exigibilidade do crédito tributário impugnado imediatamente, na forma do inciso III do caput do art. 151 (inciso I); que os julgamentos de primeira e segunda instâncias serão realizados conforme legislação específica (inciso II); que da decisão de primeira instância caberão recurso voluntário e remessa necessária, conforme legislação específica (inciso III); e que, quando houver instância superior, caberá recurso especial contra decisão de segunda instância que conferir à legislação tributária e aduaneira interpretação diversa daquela que lhe tenha atribuído outro colegiado do mesmo tribunal administrativo (inciso IV). O § 1º dispõe que caberão embargos de declaração, que terão o efeito de interromper o prazo para a interposição de outros recursos, por qualquer das partes, para esclarecer obscuridade, suprir omissão ou eliminar contradição ou erro material. O § 2º dispõe que não caberá recurso hierárquico a Secretário de Estado, a Ministro de Estado ou a qualquer outro integrante do Poder Executivo em face de decisão definitiva favorável ao sujeito passivo proferida em processo administrativo fiscal.'),
(208,'Art. 208-D','Recursos, defesas, incidentes e prazos no processo administrativo fiscal','Será garantido às partes o direito à apresentação de impugnação, em 20 dias contados da ciência da lavratura do auto de infração (inciso I); à interposição de recurso voluntário, em 20 dias contados da ciência da decisão de primeira instância que lhes for desfavorável (inciso II); à interposição de recurso especial, em 20 dias contados da ciência da decisão de segunda instância desfavorável, nas hipóteses previstas na legislação, quando houver instância superior (inciso III); e à oposição de embargos de declaração, em 5 dias contados da ciência do despacho com conteúdo decisório, da decisão ou do acórdão, em caso de obscuridade, omissão, contradição ou erro material (inciso IV). O § 1º dispõe que as pautas de julgamento deverão ser divulgadas com antecedência mínima de 10 dias. O § 2º iguala os prazos de contrarrazões aos dos incisos II, III e IV. O § 3º dispõe que os prazos serão contados em dias úteis, excluindo-se o dia do início e incluindo-se o do vencimento. O § 4º dispõe que os prazos somente se iniciam ou vencem em dia de expediente normal no órgão em que tramite o processo ou deva ser praticado o ato. O § 5º suspende o curso do prazo processual nos dias compreendidos entre 20 de dezembro e 20 de janeiro, inclusive. O § 6º permite às partes solicitar a retirada de pauta quando o julgamento estiver previsto para esse período. O § 7º dispõe que o contribuinte deverá mencionar os motivos de fato e de direito que amparam seu pedido na primeira oportunidade de manifestação processual perante a Fazenda Pública. O § 8º dispõe que as provas documentais deverão ser apresentadas nesse momento. O § 9º admite novas provas ou razões de direito posteriormente, desde que demonstrada a impossibilidade de apresentação oportuna por motivo de força maior (inciso I), que se refiram a fato ou direito superveniente (inciso II) ou que se destinem a contrapor fatos ou razões posteriormente trazidos aos autos (inciso III).'),
(208,'Art. 208-E','Dever de informar a existência de ação judicial','É dever do sujeito passivo informar se a matéria impugnada no âmbito do processo administrativo fiscal foi submetida à apreciação judicial, devendo ser juntada cópia da petição, acompanhada dos documentos necessários, para que a autoridade administrativa avalie a identidade dos objetos (Lei Complementar n. 236, de 2026). O parágrafo único dispõe que a propositura de ação judicial pelo sujeito passivo com o mesmo objeto de processo administrativo fiscal importará em renúncia ao poder de recorrer na esfera administrativa e desistência do recurso acaso interposto.'),
(208,'Art. 208-F','Fundamentação e publicidade das decisões administrativas','As decisões e os acórdãos deverão indicar com clareza os pressupostos de fato e de direito que os determinaram (Lei Complementar n. 236, de 2026). O parágrafo único dispõe que as administrações tributárias deverão publicizar as decisões e os acórdãos proferidos no curso do contencioso administrativo, disponibilizando-os para consulta.'),
(208,'Art. 208-G','Efeito vinculante no processo administrativo fiscal','No âmbito do processo administrativo fiscal, têm efeito vinculante os pronunciamentos do Supremo Tribunal Federal e do Superior Tribunal de Justiça com efeito vinculante no âmbito judicial, inclusive as súmulas vinculantes do STF, na forma do art. 103-A da Constituição Federal (alínea a); as decisões transitadas em julgado do STF ou do STJ sob a sistemática da repercussão geral ou dos recursos repetitivos (alínea b); e as decisões transitadas em julgado do STF em sede de controle concentrado de constitucionalidade, na forma do § 2º do art. 102 da Constituição Federal (alínea c), tudo conforme o inciso I; a resolução do Senado Federal que suspender a execução de lei ou de dispositivo legal, na forma do inciso X do caput do art. 52 da Constituição Federal (inciso II); e as decisões reiteradas e uniformes dos tribunais administrativos no âmbito dos entes federativos, consubstanciadas em súmulas (inciso III). O § 1º dispõe que não será lavrado auto de infração ou notificação de lançamento, negada impugnação, pedido de restituição ou recurso, nem serão inscritos em dívida ativa os créditos cuja constituição esteja fundada em matéria decidida de modo favorável ao sujeito passivo nos termos do artigo. O § 2º dispõe que o tribunal administrativo deverá manter banco eletrônico de dados atualizados com informações sobre os fundamentos determinantes da decisão consolidada em súmula e os dispositivos normativos a ela relacionados.'),
(208,'Art. 208-H','Anulação de atos e nulidades no processo administrativo fiscal','A administração deverá anular seus próprios atos quando eivados de vício de legalidade (Lei Complementar n. 236, de 2026). O § 1º dispõe que são nulos os atos e os termos lavrados por autoridade, órgão ou servidor incompetente (inciso I) e os lançamentos sem fundamentação legal (inciso III); os incisos II e IV constam como vetados e estão registrados como não vigentes. O § 2º dispõe que as intimações serão nulas quando feitas sem observância das prescrições legais, mas o comparecimento do administrado ou da Fazenda Pública supre a falta ou a irregularidade presente no ato de comunicação. O § 3º dispõe que a nulidade de qualquer ato somente prejudicará os atos posteriores que dele diretamente dependam ou sejam consequência. O § 4º dispõe que, ao declarar a nulidade, a autoridade indicará os atos por ela atingidos, ordenando as providências necessárias ao prosseguimento ou à solução do processo. O § 5º dispõe que, quando puder decidir o mérito a favor do sujeito passivo a quem aproveitaria a declaração de nulidade, a autoridade julgadora não a pronunciará nem mandará repetir o ato ou suprir-lhe a falta.'),
(208,'Art. 208-I','Diferenciação de trâmite e julgamento','O trâmite e o julgamento do processo administrativo fiscal poderão ser diferenciados em função do valor do crédito tributário discutido, do indébito pleiteado pelo sujeito passivo ou do porte da pessoa jurídica, nos termos da legislação específica (Lei Complementar n. 236, de 2026).'),
(208,'Art. 208-J','Sobrestamento por precedente qualificado','A tramitação dos processos administrativos fiscais que versem sobre uma mesma questão jurídica será sobrestada automaticamente quando o Supremo Tribunal Federal ou o Superior Tribunal de Justiça houver determinado a suspensão coletiva de processos judiciais para a resolução da mesma questão jurídica mediante precedente qualificado (Lei Complementar n. 236, de 2026). O § 1º dispõe que, caso o processo contenha outras questões jurídicas independentes, o crédito tributário a elas correspondente poderá ser transferido para autos apartados, que não serão afetados pelo sobrestamento. O § 2º dispõe que o artigo não obsta a concessão de medida liminar ou tutela provisória, quando presentes os requisitos previstos na legislação processual civil.')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
